from typing import List

def getMaximumEdges(employee_nodes: int, employee_from: List[int], employee_to: List[int],
                    special_employees: List[int], max_connections: int) -> int:
    n = employee_nodes
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(u: int) -> int:
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    for u, v in zip(employee_from, employee_to):
        ru, rv = find(u), find(v)
        if ru != rv:
            if size[ru] < size[rv]:
                ru, rv = rv, ru
            parent[rv] = ru
            size[ru] += size[rv]

    special_roots = {find(s) for s in special_employees}
    special_sizes = sorted((size[r] for r in special_roots), reverse=True)
    free = sum(size[r] for r in range(1, n + 1) if find(r) == r and r not in special_roots)

    # 按大小降序，每 max_connections 个特殊分量并成一组；无特殊员工的点全部并进最大的一组
    groups = [sum(special_sizes[i:i + max_connections])
              for i in range(0, len(special_sizes), max_connections)]
    groups[0] += free
    return sum(g * (g - 1) // 2 for g in groups) - len(employee_from)
